package com.pandinila.broadband_management.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="incidents") public class Incident { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String incidentNumber; @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @Enumerated(EnumType.STRING) private Enums.IncidentType incidentType; @Column(length=2000) private String description; @Enumerated(EnumType.STRING) private Enums.Priority priority; private String severity; private double riskScore,qualityScore; @ManyToOne @JoinColumn(name="assigned_team_id") private SupportTeam assignedTeam; @ManyToOne @JoinColumn(name="assigned_engineer_id") private Engineer assignedEngineer; @Enumerated(EnumType.STRING) private Enums.IncidentStatus status=Enums.IncidentStatus.NEW; private Instant createdAt=Instant.now(),updatedAt=Instant.now(),resolvedAt; @Column(length=2000) private String resolutionNotes;
 public Long getId(){return id;} public String getIncidentNumber(){return incidentNumber;} public void setIncidentNumber(String v){incidentNumber=v;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public Enums.IncidentType getIncidentType(){return incidentType;} public void setIncidentType(Enums.IncidentType v){incidentType=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Enums.Priority getPriority(){return priority;} public void setPriority(Enums.Priority v){priority=v;} public String getSeverity(){return severity;} public void setSeverity(String v){severity=v;} public double getRiskScore(){return riskScore;} public void setRiskScore(double v){riskScore=v;} public double getQualityScore(){return qualityScore;} public void setQualityScore(double v){qualityScore=v;} public SupportTeam getAssignedTeam(){return assignedTeam;} public void setAssignedTeam(SupportTeam v){assignedTeam=v;} public Engineer getAssignedEngineer(){return assignedEngineer;} public void setAssignedEngineer(Engineer v){assignedEngineer=v;} public Enums.IncidentStatus getStatus(){return status;} public void setStatus(Enums.IncidentStatus v){status=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public Instant getResolvedAt(){return resolvedAt;} public void setResolvedAt(Instant v){resolvedAt=v;} public String getResolutionNotes(){return resolutionNotes;} public void setResolutionNotes(String v){resolutionNotes=v;} @PreUpdate void touched(){updatedAt=Instant.now();}
}
